// Build Metadata Filters
// Constructs Qdrant filter payload from user-provided metadata criteria

const inputData = $input.all();
const outputs = [];

for (const item of inputData) {
  const input = item.json;

  // Build filter conditions
  const filterConditions = [];

  // Department filter
  if (input.department) {
    filterConditions.push({
      key: "department",
      match: { value: input.department.toUpperCase() }
    });
  }

  // Document type filter
  if (input.document_type) {
    filterConditions.push({
      key: "document_type_category",
      match: { value: input.document_type.toLowerCase() }
    });
  }

  // Document code exact match
  if (input.document_code) {
    filterConditions.push({
      key: "document_id",
      match: { value: input.document_code.toUpperCase() }
    });
  }

  // Version filter
  if (input.version) {
    filterConditions.push({
      key: "version",
      match: { value: input.version }
    });
  }

  // Date range filters
  if (input.date_from) {
    filterConditions.push({
      key: "updated_date",
      range: { gte: input.date_from }
    });
  }

  if (input.date_to) {
    filterConditions.push({
      key: "updated_date",
      range: { lte: input.date_to }
    });
  }

  // Standard compliance filter
  if (input.standard_compliance) {
    filterConditions.push({
      key: "standard_compliance",
      match: { value: input.standard_compliance }
    });
  }

  // Build the search payload
  const searchPayload = {
    query: input.query || "",
    limit: input.limit !== undefined ? parseInt(input.limit) : 20,
    filter: filterConditions.length > 0 ? {
      must: filterConditions
    } : undefined,
    min_score: input.min_score !== undefined ? parseFloat(input.min_score) : 0.7,
    min_quality: input.min_quality !== undefined ? parseFloat(input.min_quality) : 0.65
  };

  // Validate limit
  if (searchPayload.limit < 1 || searchPayload.limit > 100) {
    throw new Error("Limit must be between 1 and 100");
  }

  // If no query and no filters, throw error
  if (!searchPayload.query && filterConditions.length === 0) {
    throw new Error("Must provide either a query or at least one filter (department, document_type, document_code, etc.)");
  }

  outputs.push({ json: searchPayload });
}

return outputs;

// Format Filtered Results
// Formats metadata search results with proper grouping and citations

const inputData = $input.all();
const outputs = [];

for (const item of inputData) {
  const response = item.json;

  // Check if we have results
  if (!response.results || response.results.length === 0) {
    outputs.push({
      json: {
        success: true,
        message: "No documents found matching your filters. Try: (1) removing some filters, (2) broader search terms, or (3) different departments.",
        query: response.query || "",
        filters_applied: extractAppliedFilters(response),
        results_count: 0,
        results: [],
        results_by_department: {},
        results_by_type: {}
      }
    });
    continue;
  }

  // Format results with proper citations
  const formattedResults = response.results.map((result, index) => {
    return {
      rank: index + 1,
      document_code: result.document_id || "Unknown",
      title: result.document_name || "Untitled Document",
      department: result.department || "Unknown",
      document_type: result.document_type_category || "Unknown",
      document_type_code: extractTypeCode(result.document_id),
      version: result.version || "N/A",
      updated_date: result.updated_date || null,
      standard_compliance: result.standard_compliance || [],
      content_snippet: result.content ? result.content.substring(0, 250) + "..." : "",
      relevance_score: result.score ? result.score.toFixed(3) : "N/A",
      quality_score: result.quality_score ? result.quality_score.toFixed(3) : "N/A",
      sharepoint_url: result.document_url || null,

      // Generate citation format
      citation: `**${result.document_id || "Unknown"}** (${
        result.document_name || "Untitled"
      }${result.version ? ", " + result.version : ""})`
    };
  });

  // Group by department
  const byDepartment = groupBy(formattedResults, 'department');

  // Group by document type
  const byType = groupBy(formattedResults, 'document_type');

  // Create formatted response
  const formattedResponse = {
    success: true,
    search_type: "metadata_filtered",
    query: response.query || "(no query - filter only)",
    filters_applied: extractAppliedFilters(response),
    results_count: formattedResults.length,
    results: formattedResults,

    // Grouped results for easy navigation
    results_by_department: Object.keys(byDepartment).map(dept => ({
      department: dept,
      count: byDepartment[dept].length,
      documents: byDepartment[dept].map(r => r.citation)
    })),

    results_by_type: Object.keys(byType).map(type => ({
      type: type,
      count: byType[type].length,
      documents: byType[type].map(r => r.citation)
    })),

    // Generate summary
    summary: generateFilteredSummary(formattedResults, response.query),

    // Metadata
    metadata: {
      search_time_ms: response.search_time_ms || null,
      total_documents_searched: response.total_points || null,
      min_score_threshold: response.min_score || 0.7,
      min_quality_threshold: response.min_quality || 0.95
    }
  };

  outputs.push({ json: formattedResponse });
}

// Helper functions
function groupBy(array, key) {
  return array.reduce((result, item) => {
    const groupKey = item[key] || 'Unknown';
    if (!result[groupKey]) {
      result[groupKey] = [];
    }
    result[groupKey].push(item);
    return result;
  }, {});
}

function extractTypeCode(documentId) {
  if (!documentId) return "Unknown";
  const match = documentId.match(/BMS-[A-Z]+-([A-Z]+)-/);
  return match ? match[1] : "Unknown";
}

function extractAppliedFilters(response) {
  const filters = [];
  if (response.filter && response.filter.must) {
    response.filter.must.forEach(condition => {
      if (condition.match) {
        filters.push(`${condition.key}=${condition.match.value}`);
      } else if (condition.range) {
        if (condition.range.gte) {
          filters.push(`${condition.key}>=${condition.range.gte}`);
        }
        if (condition.range.lte) {
          filters.push(`${condition.key}<=${condition.range.lte}`);
        }
      }
    });
  }
  return filters;
}

function generateFilteredSummary(results, query) {
  if (results.length === 0) {
    return `No results found${query ? ` for "${query}"` : ""}.`;
  }

  const deptCounts = results.reduce((acc, r) => {
    acc[r.department] = (acc[r.department] || 0) + 1;
    return acc;
  }, {});

  const deptSummary = Object.keys(deptCounts)
    .map(dept => `${dept} (${deptCounts[dept]})`)
    .join(", ");

  const topResults = results.slice(0, 3);
  const citations = topResults.map(r => r.citation).join("\n");

  return `Found ${results.length} documents${query ? ` for "${query}"` : ""}\n\nBy department: ${deptSummary}\n\nTop results:\n${citations}`;
}

return outputs;
